-- Marie Curie
SELECT 'obra_041_curie_tese', 'pub_curie_marie_skodowska_curie', 'pesquisa', 'Recherches sur les substances radioactives (Tese de Doutorado)', 'Física Nuclear', 1903, NULL, 'Tese de doutorado na Sorbonne apresentando a descoberta da radioatividade de minérios de urânio e do rádio.', 'loc-fr-paris'
WHERE EXISTS (SELECT 1 FROM pessoas WHERE id = 'pub_curie_marie_skodowska_curie') AND NOT EXISTS (SELECT 1 FROM obras_culturais WHERE id = 'obra_041_curie_tese')
ON CONFLICT(id) DO UPDATE SET titulo = excluded.titulo, detalhes = excluded.detalhes, ano = excluded.ano, local_id = excluded.local_id;

SELECT 'obra_041_curie_traite', 'pub_curie_marie_skodowska_curie', 'livro', 'Traité de radioactivité (Tratado de Radioatividade em 2 Volumes)', 'Tratado Científico', 1910, NULL, 'Tratado de referência clássica internacional compilando os fundamentos da física e química das radiações nucleares.', 'loc-fr-paris'
WHERE EXISTS (SELECT 1 FROM pessoas WHERE id = 'pub_curie_marie_skodowska_curie') AND NOT EXISTS (SELECT 1 FROM obras_culturais WHERE id = 'obra_041_curie_traite')
ON CONFLICT(id) DO UPDATE SET titulo = excluded.titulo, detalhes = excluded.detalhes, ano = excluded.ano, local_id = excluded.local_id;

SELECT 'obra_041_curie_radium_polonium', 'pub_curie_marie_skodowska_curie', 'pesquisa', 'Découverte du Radium et du Polonium (com Pierre Curie)', 'Química dos Elementos', 1898, NULL, 'Isolamento e anúncio perante a Academia das Ciências de Paris de dois novos elementos químicos radioativos.', 'loc-fr-paris'
WHERE EXISTS (SELECT 1 FROM pessoas WHERE id = 'pub_curie_marie_skodowska_curie') AND NOT EXISTS (SELECT 1 FROM obras_culturais WHERE id = 'obra_041_curie_radium_polonium')
ON CONFLICT(id) DO UPDATE SET titulo = excluded.titulo, detalhes = excluded.detalhes, ano = excluded.ano, local_id = excluded.local_id;

